(() => {
  'use strict';const slug=location.pathname.split('/').filter(Boolean).pop(),allowed=['recorder','video','audio','subtitles','redact','convert'];if(!allowed.includes(slug))return;const $=id=>document.getElementById(id),E=(t,text)=>{const n=document.createElement(t);if(text!=null)n.textContent=text;return n;};
  const panel=E('section');panel.className='wb-panel wb-no-print';panel.innerHTML='<h2>编辑工程与连续工作流</h2><p class="wb-note">工程只保存编辑参数和素材名称 / 大小，不包含音视频。恢复工程后须重新选择原素材。跨页传递需明确确认，暂存素材上限 64 MB，30 分钟有效（过期素材在下次打开工作台时清理）；成功接收后删除暂存。长会议和大文件请从本地重新选择，不复制进浏览器存储。</p><div class="wb-row"><input id="media-project-name" maxlength="80" placeholder="工程名称" aria-label="工程名称"><button id="media-project-download">下载编辑工程</button><label>恢复工程<input id="media-project-import" type="file" accept=".json"></label><button id="media-project-save">仅保存参数到本浏览器</button><button id="media-project-load">载入本机参数</button><button id="media-project-clear">删除本机工程参数</button></div><div class="wb-row" id="media-transfer-actions"><label>传递内容<select id="media-transfer-kind"><option value="result">处理结果（须先生成）</option><option value="source">原素材（不含剪切或脱敏）</option></select></label><label>继续处理<select id="media-target"></select></label><button id="media-transfer">确认后传递素材</button><button id="media-transfer-clear">清除全部待接收素材</button></div><div id="media-incoming" hidden><p id="media-incoming-description"></p><button id="media-receive">接收并载入素材</button><button id="media-reject">拒绝并删除暂存</button></div><p id="media-workflow-status" class="wb-status" role="status"></p>';
  const details=E('details');details.className='wb-more';details.id='media-options';details.append(E('summary','工程保存、恢复与跨页素材传递'));for(const n of [...panel.children])if(!['media-incoming','media-workflow-status'].includes(n.id)&&n.tagName!=='H2')details.append(n);panel.querySelector('h2').after(details);const main=document.querySelector('main'),bar=main.querySelector(':scope>.intro')||main.querySelector('.wb-bar');if(bar)bar.after(panel);else main.prepend(panel);const message=t=>$('media-workflow-status').textContent=t;let busy=false;
  const api=()=>window.MediaWorkbench;const key='yj-media-project-'+slug+'-v1';
  function validate(v){if(!v||v.app!=='yj-media-edit-project'||v.version!==1||v.tool!==slug||typeof v.name!=='string'||v.name.length>80||!v.settings||typeof v.settings!=='object'||new Blob([JSON.stringify(v)]).size>2*1048576)throw Error('工程格式不匹配或超过 2 MB');return v;}
  const task=fn=>async()=>{if(busy)return;busy=true;try{if(!api())throw Error('工具尚未就绪，请稍候');await fn();}catch(e){message(e.message);}finally{busy=false;}};
  function project(){const settings=api().project();return validate({app:'yj-media-edit-project',version:1,tool:slug,name:$('media-project-name').value.trim()||'未命名工程',savedAt:Date.now(),settings});}
  function download(v){const u=URL.createObjectURL(new Blob([JSON.stringify(v)],{type:'application/json'})),a=E('a');a.href=u;a.download=slug+'-编辑工程.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
  $('media-project-download').onclick=task(()=>{download(project());message('已发起工程参数下载；请另行保管原素材。');});
  $('media-project-save').onclick=task(()=>{const v=project();if(!confirm('仅保存编辑参数与素材名称到本浏览器，不保存音视频。继续？'))return;localStorage.setItem(key,JSON.stringify(v));message('工程参数已保存，原素材未写入存储。');});
  async function restore(v){validate(v);if(!confirm('用此工程参数替换当前编辑参数？原素材不会被修改。'))return;await api().restore(v.settings);$('media-project-name').value=v.name;message('参数已载入。需要原素材的工具请重新选择原文件，并核对选区与时间。');}
  $('media-project-load').onclick=task(async()=>{const raw=localStorage.getItem(key);if(!raw)throw Error('还没有保存本机工程');await restore(JSON.parse(raw));});
  $('media-project-import').onchange=task(async()=>{try{const f=$('media-project-import').files[0];if(!f||f.size>2*1048576)throw Error('请选择 2 MB 内工程');await restore(JSON.parse(await f.text()));}finally{$('media-project-import').value='';}});
  $('media-project-clear').onclick=task(()=>{if(confirm('删除此工具的本机工程参数？当前内存和下载文件不受影响。')){localStorage.removeItem(key);message('本机工程参数已删除。');}});
  function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('yj-media-handoff-v1.html',1);r.onupgradeneeded=()=>r.result.createObjectStore('transfers',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
  async function store(mode,fn){const d=await db();try{return await new Promise((resolve,reject)=>{const tx=d.transaction('transfers',mode),r=fn(tx.objectStore('transfers'));let value;r.onsuccess=()=>value=r.result;tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}finally{d.close();}}
  async function clean(){const all=await store('readonly',s=>s.getAll());for(const x of all)if(x.expires<=Date.now())await store('readwrite',s=>s.delete(x.id));}
  const names={video:'视频快剪',subtitles:'字幕与章节',redact:'画面脱敏',audio:'音频处理',convert:'统一处理队列'};const targets=slug==='convert'?[]:slug==='audio'?['convert']:['convert','video','subtitles','redact'].filter(x=>x!==slug);targets.forEach(x=>$('media-target').add(new Option(names[x],x)));$('media-transfer-actions').hidden=!targets.length;
  $('media-transfer').onclick=task(async()=>{const output=$('media-transfer-kind').value==='result';const source=output?api().result?.():api().source?.();if(!(source instanceof Blob)||!source.size)throw Error('当前选择没有素材；处理结果须先完成录制或剪切，原素材须先选择视频');if(api().busy?.())throw Error('请先完成当前处理');if(source.size>64*1048576)throw Error('素材超过 64 MB，请下载后在目标工具重新选择，不复制大文件进浏览器');const target=$('media-target').value;if(!targets.includes(target))throw Error('目标无效');if(!confirm(`将${output?'处理结果':'未经剪切或脱敏的原素材'}临时存到此浏览器并打开“${names[target]}”？素材可能敏感，30 分钟有效，接收后删除暂存。`))return;await clean();const all=await store('readonly',s=>s.getAll());if(all.length>=3)throw Error('已有 3 份待接收素材，请先接收或清除');const id=crypto.randomUUID(),name=source.name||'工作台输出.'+(({'audio/mpeg':'mp3','audio/wav':'wav','audio/mp4':'m4a','video/mp4':'mp4'})[source.type]||'webm');await store('readwrite',s=>s.put({id,from:slug,target,name,size:source.size,type:source.type,expires:Date.now()+30*60000,file:source}));message('已暂存，即将打开目标工具。原页面素材保留；离开前仍请下载重要结果。');location.assign('../'+target+'/?handoff='+encodeURIComponent(id));});
  $('media-transfer-clear').onclick=task(async()=>{if(confirm('清除所有尚未接收的本地暂存素材？原文件不受影响。')){await store('readwrite',s=>s.clear());$('media-incoming').hidden=true;message('待接收素材已清除。');}});
  const id=new URLSearchParams(location.search).get('handoff');let incoming;
  async function inspect(){await clean();if(!id||!/^[0-9a-f-]{36}$/.test(id))return;incoming=await store('readonly',s=>s.get(id));if(!incoming||incoming.target!==slug||incoming.expires<=Date.now()){message('待接收素材不存在或已过期，请重新选择本地文件。');return;}if(incoming.size>64*1048576||!(incoming.file instanceof Blob)||incoming.file.size!==incoming.size)throw Error('待接收素材无效');$('media-incoming').hidden=false;$('media-incoming-description').textContent=`来自 ${incoming.from}：${incoming.name}，${(incoming.size/1048576).toFixed(1)} MB。${slug==='convert'?'接收会新增一个队列任务，不会立即运行。':'接收会替换当前预览素材，请先保存当前工程。'}`;}
  $('media-receive').onclick=task(async()=>{if(!incoming||incoming.expires<=Date.now())throw Error('暂存已过期');const file=new File([incoming.file],incoming.name,{type:incoming.type});await api().accept(file);await store('readwrite',s=>s.delete(incoming.id));incoming=null;$('media-incoming').hidden=true;history.replaceState(null,'',location.pathname);message('已接收素材并删除本机暂存，请核对预览。');});
  $('media-reject').onclick=task(async()=>{if(incoming)await store('readwrite',s=>s.delete(incoming.id));incoming=null;$('media-incoming').hidden=true;history.replaceState(null,'',location.pathname);message('已拒绝并删除暂存。');});
  if(slug==='convert'){details.hidden=true;panel.querySelector('h2').textContent='接收其它工作台素材';panel.hidden=!id;}
  else{const row=E('div');row.className='wb-row';const link=E('a','打开统一处理队列 ↗');link.className='button';link.href='index.html';row.append(link,E('span','批量裁剪、转换、短片试听与结果命名；素材只在本机处理。'));panel.querySelector('h2').after(row);}
  inspect().catch(e=>message('跨页暂存不可用，可使用本地文件：'+e.message));setInterval(()=>clean().catch(()=>{}),60000);
})();
